def solve_v1(grid):
    n = len(grid)
    m = len(grid[0])

    # Find seed position
    seed_pos = None
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 2:
                seed_pos = (r, c)
                break

    result = [row[:] for row in grid]

    if seed_pos is None:
        return result

    sr, sc = seed_pos

    # Mark cells to convert to 2
    cells_to_convert = set()

    # Rule 1: Fill horizontally between consecutive 8s in each row
    for r in range(n):
        cols_with_8 = [(c, grid[r][c]) for c in range(m) if grid[r][c] != 0]
        i = 0
        while i < len(cols_with_8):
            c1 = cols_with_8[i][0]
            # Look for next 8
            j = i + 1
            while j < len(cols_with_8) and cols_with_8[j][0] == c1:
                j += 1

            if j < len(cols_with_8):
                c2 = cols_with_8[j][0]
                # Fill between c1+1 and c2-1
                for c in range(c1 + 1, c2):
                    if 0 <= r < n and 0 <= c < m and grid[r][c] == 0:
                        cells_to_convert.add((r, c))

            i = j + 1

    # Rule 2: Fill vertically between consecutive 8s in each column
    for c in range(m):
        rows_with_8 = [(r, grid[r][c]) for r in range(n) if grid[r][c] != 0]
        i = 0
        while i < len(rows_with_8):
            r1 = rows_with_8[i][0]
            j = i + 1
            while j < len(rows_with_8) and rows_with_8[j][0] == r1:
                j += 1

            if j < len(rows_with_8):
                r2 = rows_with_8[j][0]
                for r in range(r1 + 1, r2):
                    if 0 <= r < n and 0 <= c < m and grid[r][c] == 0:
                        cells_to_convert.add((r, c))

            i = j + 1

    # Apply conversions
    for r, c in cells_to_convert:
        result[r][c] = 2

    return result

