def solve_v2(grid):
    n = len(grid)
    m = len(grid[0])

    # Find seed position
    seed_pos = None
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 2:
                seed_pos = (r, c)
                break

    result = [row[:] for row in grid]

    if seed_pos is None:
        return result

    sr, sc = seed_pos

    def can_reach(seed, r, c):
        """Check if cell (r,c) can reach seed by moving only through non-zero cells"""
        q = [(seed[0], seed[1])]
        visited = {seed}
        while q:
            cur_r, cur_c = q.pop(0)
            if cur_r == r and cur_c == c:
                return True
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = cur_r + dr, cur_c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    val = grid[nr][nc]
                    if val != 0 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
        return False

    def can_reach_8(r, c):
        """Check if cell (r,c) can reach ANY 8 by moving only through non-zero cells"""
        q = [(r, c)]
        visited = {(r, c)}
        while q:
            cur_r, cur_c = q.pop(0)
            if grid[cur_r][cur_c] == 8:
                return True
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = cur_r + dr, cur_c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    val = grid[nr][nc]
                    if val != 0 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
        return False

    # A 0-cell becomes 2 if it can reach BOTH the seed AND some 8
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 0:
                if can_reach(seed_pos, r, c) and can_reach_8(r, c):
                    result[r][c] = 2

    return result

