def has_horizontal_gap(grid, r):
    m = len(grid[0])
    nonzero_cols = [c for c in range(m) if grid[r][c] != 0]
    if len(nonzero_cols) < 2:
        return False
    for i in range(len(nonzero_cols)-1):
        for c in range(nonzero_cols[i]+1, nonzero_cols[i+1]):
            if grid[r][c] == 0:
                return True
    return False

def has_any_vertical_gap_in_column_set(col_set, grid):
    """Check if any column in col_set has a vertical gap"""
    n = len(grid)
    for c in col_set:
        nonzero_rows = [r for r in range(n) if grid[r][c] != 0]
        if len(nonzero_rows) >= 2:
            for i in range(len(nonzero_rows)-1):
                for r in range(nonzero_rows[i]+1, nonzero_rows[i+1]):
                    if grid[r][c] == 0:
                        return True
    return False

